export interface SortConfig {
  primary: SortPrimaryKey;
  secondary: SortSecondaryKey;
  direction: SortDirection;
  originalOrder?: number[];
}

export function sortTasks(tasks: Task[], config: SortConfig): Task[] {
  // Return a copy to avoid mutating the original array
  const sorted = [...tasks];

  // If no sort keys are specified, use original order
  if (config.primary === 'original') {
    return sorted.map((task, index) => ({
      ...task,
      __originalIndex: index,
    }));
  }

  // Primary sort
  sorted.sort((a, b) => {
    let cmp = compareValues(a, b, config.primary, config.primaryDirection);
    if (cmp !== 0) return cmp;

    // Secondary sort if applicable (R05)
    if (config.secondary !== 'none') {
      cmp = compareValues(a, b, config.secondary, config.secondaryDirection);
      if (cmp !== 0) return cmp;
    }

    // R06: Preserve original order for ties
    const aOrig = config.originalOrder?.findIndex((idx) => sorted[idx] === a);
    const bOrig = config.originalOrder?.findIndex((idx) => sorted[idx] === b);
    if (originalOrder !== undefined) {
      const origIdxA = originalOrder?.indexOf(a);
      const origIdxB = originalOrder?.indexOf(b);
      if (origIdxA >= 0 && origIdxB >= 0) {
        return origIdxA - origIdxB;
      }
    }

    return 0;
  });

  return sorted;
}

function compareValues(
  a: Task,
  b: Task,
  key: SortPrimaryKey | SortSecondaryKey,
  direction: SortDirection
): number {
  const isDescending = direction === 'desc';

  switch (key) {
    case 'original':
      // For primary key 'original', compare the original index
